head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;

//////////////////////////////////////
scwin.key_row = '';
scwin.isur_id = '';
scwin.corp_usr_tp_cd = '';
scwin.contn_id = '';
scwin.contn_grp_id = '';
scwin.ans_obj_contn_id = '';
scwin.noti_obj_sys_tp_cd = '';
scwin.ques_bz_tp_cd = '';
scwin.opn_yn = '';
scwin.reply_yn = '';
scwin.mode = 'I';
//////////////////////////////////////

scwin.vScrenID = "ULDSTF30341.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.initPage = function() {
    $c.stf.showObj(txb_REPLY_YN, false);
    //showObj(btn_Delete, false);
    if (scwin.reply_yn == 'Y') {
        //미답변상태
        $c.stf.showObj(btn_Reply, false);
    }
};
scwin.fn_SetCode = function() {
    scwin.key_row = frame.opener.scwin.key_row;
    scwin.isur_id = frame.opener.dts_qnaList.getCellData(scwin.key_row, "ISUR_CD");
    scwin.corp_usr_tp_cd = frame.opener.dts_qnaList.getCellData(scwin.key_row, "CORP_USR_TP_CD");
    scwin.contn_id = frame.opener.dts_qnaList.getCellData(scwin.key_row, "CONTN_ID");
    scwin.contn_grp_id = frame.opener.dts_qnaList.getCellData(scwin.key_row, "CONTN_GRP_ID");
    scwin.ans_obj_contn_id = frame.opener.dts_qnaList.getCellData(scwin.key_row, "ANS_OBJ_CONTN_ID");
    scwin.noti_obj_sys_tp_cd = frame.opener.dts_qnaList.getCellData(scwin.key_row, "NOTI_OBJ_SYS_TP_CD");
    scwin.ques_bz_tp_cd = frame.opener.dts_qnaList.getCellData(scwin.key_row, "QUES_BZ_TP_CD");
    scwin.opn_yn = frame.opener.dts_qnaList.getCellData(scwin.key_row, "OPN_YN");
    scwin.reply_yn = frame.opener.dts_qnaList.getCellData(scwin.key_row, "REPLY_YN");
    //alert("contn_id : " + contn_id + " : contn_grp_id : " + contn_grp_id + " : ans_obj_contn_id : " + ans_obj_contn_id + " : noti_obj_sys_tp_cd : " + noti_obj_sys_tp_cd);
    //alert("opn_yn : " + opn_yn + " : reply_yn : " + reply_yn);

};
scwin.fn_search = function() {
    var url = "/VocQnA.do?method=readVocQnA";
    url += "&CONTN_ID=" + scwin.contn_id;
    url += "&CONTN_GRP_ID=" + scwin.contn_grp_id;
    url += "&ANS_OBJ_CONTN_ID=" + scwin.ans_obj_contn_id;
    url += "&NOTI_OBJ_SYS_TP_CD=" + scwin.noti_obj_sys_tp_cd;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    //alert(url);
    dts_MASTER.DataID = encodeURI(url);
    dts_MASTER.Reset();
    url = "/VocQnA.do?method=readVocQnAFile";
    url += "&CONTN_ID=" + scwin.contn_id;
    url += "&CONTN_GRP_ID=" + scwin.contn_grp_id;
    url += "&ANS_OBJ_CONTN_ID=" + scwin.ans_obj_contn_id;
    url += "&NOTI_OBJ_SYS_TP_CD=" + scwin.noti_obj_sys_tp_cd;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_FILE_LIST.DataID = encodeURI(url);
    dts_FILE_LIST.Reset();
};
scwin.fn_DownLoad = function(row, colid) {
    var filename = dts_FILE_LIST.getCellData(row, "ATTACH_FILE_NM");
    if (filename == "") return;
    if (colid == "ATTACH_FILE_NM") {
        var vCONTN_ID = dts_FILE_LIST.getCellData(row, "CONTN_ID");
        var vCONTN_GRP_ID = dts_FILE_LIST.getCellData(row, "CONTN_GRP_ID");
        var vANS_OBJ_CONTN_ID = dts_FILE_LIST.getCellData(row, "ANS_OBJ_CONTN_ID");
        var vNOTI_OBJ_SYS_TP_CD = dts_FILE_LIST.getCellData(row, "NOTI_OBJ_SYS_TP_CD");
        var vCONTN_ATTACH_SEQ = dts_FILE_LIST.getCellData(row, "CONTN_ATTACH_SEQ");
        var url = "/filedownload.do?gubun=20";
        url += "&contn_id=" + vCONTN_ID;
        url += "&contn_grp_id=" + vCONTN_GRP_ID;
        url += "&ans_obj_contn_id=" + vANS_OBJ_CONTN_ID;
        url += "&noti_obj_sys_tp_cd=" + vNOTI_OBJ_SYS_TP_CD;
        url += "&contn_attach_seq=" + vCONTN_ATTACH_SEQ;
        //alert(url);
        //location.href = "/filedownload.do?file_id=" + vCONTN_ID + "&attach_seq=" + vCONTN_ATTACH_SEQ + "&gubun=16";
        location.href = url;
    }
};
scwin.fn_Reply = async function() {
    await $c.frame.CreateDialogFrame("ULDSTF30342", "/bizspt/ULDSTF30342.gfm", "고객의소리 Q&A 답변", 520, 50, 600, 460 + 30, "window");
};
scwin.btn_Reply_onclick = function() {
    scwin.fn_Reply();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.trs_Save_OnFail = function() {
    $c.stf.alert_error(trs_Save);
};
scwin.trs_Save_OnSuccess = async function() {
    var msg = $c.stf.getMessageParam("MSG-A001", gLastJob);
    $c.win.alert(msg);
    var fr_fn_Search = $c.frame.path("../").fn_search;
    fr_fn_Search();
    await $c.frame.CloseFrame();
};
scwin.grd_FILE_LIST_OnClick = function(row, colid) {
    scwin.fn_DownLoad(row, colid);
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_SetCode();
    scwin.initPage();
    scwin.fn_search();
};
